class Solution {
public:
    int longestSquareStreak(vector<int>& a) {
        unordered_set<long long> s(a.begin(), a.end());
        int best = 0;
        for (long long v : s) {
            int len = 0;
            long long x = v;
            while (x <= 100000 && s.count(x)) { len++; x = x * x; }
            best = max(best, len);
        }
        return best >= 2 ? best : -1;
    }
};
