class Solution {
public:
    vector<int> intersection(vector<int>& a, vector<int>& b) {
        unordered_set<int> s(a.begin(), a.end());
        vector<int> out;
        for (int x : b) if (s.erase(x)) out.push_back(x);   // erase returns 1 if it was there
        return out;
    }
};
